// One item per competitor (one URL per line, commas work too).
return String($json.competitors).split(/\n|,/).map(s => s.trim()).filter(Boolean)
  .map(url => ({ json: { url }, pairedItem: { item: 0 } }))

const sites = $('Split: one item per competitor').all()
const brands = $('Get the brand kit').all()
const heroes = $input.all()
// Last week's snapshots live in the workflow's own memory. Production runs
// (the schedule) save them; manual test runs start fresh each time.
const memory = $getWorkflowStaticData('global')
memory.snapshots = memory.snapshots || {}

const textOf = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()
const firstWords = (s, n) => String(s || '').split(/\s+/).slice(0, n).join(' ')
// Responsive sites repeat the headline once per breakpoint: keep one copy.
const once = t => { const w = t.split(' '); for (let n = 4; n >= 2; n--) { if (w.length % n) continue; const k = w.length / n, c = w.slice(0, k).join(' '); if (Array.from({ length: n }, (_, i) => w.slice(i * k, (i + 1) * k).join(' ')).every(x => x === c)) return c } return t }
const verb = /^(get|start|try|sign|book|buy|shop|join|request|contact|download|see|learn|watch|create|explore|talk|schedule|order|subscribe|claim|discover|apply|install|view)\b/i

const reports = sites.map((site, i) => {
  const url = site.json.url
  const b = brands[i]?.json || {}
  const h = heroes[i]?.json || {}
  if (b.error || h.error) return { url, error: String((b.error || h.error).message || b.error || h.error) }
  const code = String(h.code || '')
  const now = {
    colors: b.colors || {},
    fonts: b.fonts || [],
    headline: once(textOf((code.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i) || code.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i) || [, ''])[1])).slice(0, 160),
    ctas: [...new Set([...code.matchAll(/<(a|button)\b[^>]*>([\s\S]*?)<\/\1>/gi)].map(m => textOf(m[2])).filter(t => verb.test(t) && t.length < 40))].slice(0, 5),
    sections: (h.sections || []).sort((a, b) => a.order - b.order).map(s => firstWords(s.label, 6)),
    checkedAt: new Date().toISOString().slice(0, 10),
  }
  const before = memory.snapshots[url]
  const changes = []
  if (before) {
    for (const role of ['primary', 'accent', 'background', 'text'])
      if ((before.colors || {})[role] !== now.colors[role]) changes.push(role + ' color: ' + (before.colors || {})[role] + ' -> ' + now.colors[role])
    if (before.fonts.join() !== now.fonts.join()) changes.push('fonts: ' + before.fonts.join(', ') + ' -> ' + now.fonts.join(', '))
    if (before.headline !== now.headline) changes.push('hero headline: "' + before.headline + '" -> "' + now.headline + '"')
    if (before.ctas.join() !== now.ctas.join()) changes.push('hero calls to action: ' + (before.ctas.join(', ') || 'none') + ' -> ' + (now.ctas.join(', ') || 'none'))
    const added = now.sections.filter(s => !before.sections.includes(s))
    const removed = before.sections.filter(s => !now.sections.includes(s))
    if (added.length) changes.push('new sections: ' + added.map(s => '"' + s + '"').join(', '))
    if (removed.length) changes.push('removed sections: ' + removed.map(s => '"' + s + '"').join(', '))
  }
  memory.snapshots[url] = now
  return { url, firstCheck: !before, lastChecked: before?.checkedAt || null, changes, now }
})

const changed = reports.filter(r => r.changes?.length).length
return [{ json: { reports, reportsText: JSON.stringify(reports, null, 2), changed, total: reports.length } }]
